record.field:
{
  "type": "object",
  "properties": {
    "origin": {"type": "string", "description": "Origin station code (e.g. NDLS) or city name (e.g. Delhi)"},
    "destination": {"type": "string", "description": "Destination station code (e.g. MMCT) or city name (e.g. Mumbai)"},
    "date": {"type": "string", "description": "Journey date in YYYY-MM-DD format"}
  },
  "required": ["origin", "destination"]
}

{
  "type": "object",
  "properties": {
    "train_number": {"type": "string", "description": "Train number (e.g. 12952) or train name"},
    "travel_class": {"type": "string", "description": "Class code: 1A, 2A, 3A, CC, EC, SL"},
    "date": {"type": "string", "description": "Journey date in YYYY-MM-DD format"}
  },
  "required": ["train_number", "travel_class"]
}

{
  "type": "object",
  "properties": {
    "train_number": {"type": "string", "description": "Train number (e.g. 12952)"},
    "travel_class": {"type": "string", "description": "Class code: 1A, 2A, 3A, CC, EC, SL"},
    "journey_date": {"type": "string", "description": "Date of journey YYYY-MM-DD"},
    "passengers": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "name": {"type": "string"},
          "age": {"type": "integer"},
          "gender": {"type": "string", "enum": ["male", "female", "other"]},
          "berth_preference": {"type": "string", "enum": ["lower", "middle", "upper", "side_lower", "side_upper", "window", "no_preference"]}
        },
        "required": ["name"]
      }
    },
    "customer_name": {"type": "string"},
    "customer_email": {"type": "string"}
  },
  "required": ["train_number", "travel_class", "journey_date"]
}

{
  "type": "object",
  "properties": {
    "pnr": {"type": "string", "description": "The PNR number of the booking to confirm (e.g. PNR-2849102847)"},
    "booking_id": {"type": "integer", "description": "Optional Odoo internal ID of the booking"}
  },
  "required": ["pnr"]
}

{
  "type": "object",
  "properties": {
    "pnr": {"type": "string", "description": "The PNR number to cancel"},
    "reason": {"type": "string", "description": "Reason for ticket cancellation"}
  },
  "required": ["pnr"]
}
